<?php declare(strict_types=1); namespace App\People\Application\Query\GetPerson; use App\People\Application\DTO\PersonView; use App\People\Domain\Repository\PersonRepository; use App\People\Domain\ValueObject\PersonId; final readonly class GetPersonHandler {public function __construct(private PersonRepository $people){} public function __invoke(GetPersonQuery $q):PersonView{$p=$this->people->findById(PersonId::fromString($q->id));if(!$p)throw new \RuntimeException('Person not found.');return new PersonView($p->id()->toString(),$p->name()->firstName(),$p->name()->lastName(),$p->dateOfBirth()?->format('Y-m-d'),$p->gender()->value,$p->email()?->value(),$p->phone()?->value(),$p->status()->value,$p->createdAt()->format(DATE_ATOM),$p->updatedAt()->format(DATE_ATOM));}}
